/* ============================================================================
 * js/assets.js — все картинки игры, встроенные прямо в код (base64, WebP).
 *
 * Зачем base64: игра запускается простым открытием index.html (file://),
 * без сервера, поэтому картинки нельзя подгружать отдельными файлами через
 * fetch — а data-URI работают везде.
 *
 * Спрайты сделаны из прикреплённых картинок: фон вырезан, размер уменьшен.
 * Все спрайты одного героя приведены к ОДНОМУ масштабу (по глазам), поэтому
 * костюмы можно рисовать с тем же drawScale, что и базовый облик.
 *
 * Поля спрайта:
 *   hero    — 'omnom' | 'cat'
 *   costume — 'base' | 'knight' | 'wizard' | 'chef' | 'winter'
 *   w, h    — размер картинки в пикселях
 *   ax, ay  — «якорь»: точка между лапками героя (x, y внутри картинки).
 *             Героя рисуем так, чтобы якорь совпал с его позицией на арене.
 * ========================================================================== */
(function () {
  'use strict';

  var sprites = {
    omnom_base: { hero: 'omnom', costume: 'base', title: 'Ам Ням', w: 183, h: 183, ax: 88, ay: 175,
      src: 'data:image/webp;base64,' },
    omnom_knight: { hero: 'omnom', costume: 'knight', title: 'Рыцарь', w: 191, h: 198, ax: 104, ay: 196,
      src: 'data:image/webp;base64,' },
    omnom_wizard: { hero: 'omnom', costume: 'wizard', title: 'Волшебник', w: 201, h: 190, ax: 108, ay: 188,
      src: 'data:image/webp;base64,' },
    omnom_chef: { hero: 'omnom', costume: 'chef', title: 'Повар', w: 228, h: 218, ax: 126, ay: 215,
      src: 'data:image/webp;base64,' },
    cat_base: { hero: 'cat', costume: 'base', title: 'Кошечка', w: 161, h: 189, ax: 82, ay: 174,
      src: 'data:image/webp;base64,' },
    cat_knight: { hero: 'cat', costume: 'knight', title: 'Рыцарка', w: 170, h: 220, ax: 89, ay: 207,
      src: 'data:image/webp;base64,' },
    cat_wizard: { hero: 'cat', costume: 'wizard', title: 'Волшебница', w: 153, h: 186, ax: 77, ay: 176,
      src: 'data:image/webp;base64,' },
    cat_winter: { hero: 'cat', costume: 'winter', title: 'Зимний наряд', w: 142, h: 237, ax: 72, ay: 211,
      src: 'data:image/webp;base64,' }
  };

  var Assets = {
    sprites: sprites,

    /** Загруженные объекты Image по имени спрайта (заполняются в load). */
    images: {},

    /**
     * Во сколько раз уменьшать спрайт при рисовании на арене.
     * 0.42 → базовые герои получаются ~75 px в высоту на арене 960×600.
     */
    drawScale: 0.42,

    /** Имя спрайта для героя в костюме: sprite('cat', 'winter') → 'cat_winter'. */
    spriteName: function (hero, costume) {
      var name = hero + '_' + (costume || 'base');
      return sprites[name] ? name : hero + '_base';
    },

    /**
     * Декодирует все картинки. Возвращает Promise, который выполняется,
     * когда всё готово (ошибка одной картинки не ломает игру — будет заглушка).
     * onProgress(done, total) — для полоски загрузки.
     */
    load: function (onProgress) {
      var names = Object.keys(sprites);
      var done = 0;
      return Promise.all(names.map(function (name) {
        return new Promise(function (resolve) {
          var img = new Image();
          img.onload = function () {
            Assets.images[name] = img;
            finish();
          };
          img.onerror = function () {
            console.warn('[assets] не удалось загрузить спрайт', name);
            finish();
          };
          function finish() {
            done++;
            if (onProgress) onProgress(done, names.length);
            resolve();
          }
          img.src = sprites[name].src;
        });
      })).then(buildDerived);
    },

    /**
     * Наряды-надстройки: готовый спрайт героя плюс дорисованные поверх вещи
     * (шапка, корона, крылышки). Регистрируются заранее (js/wardrobe.js),
     * а после загрузки картинок склеиваются в обычный спрайт — поэтому дальше
     * их рисуют, анимируют и передают по сети так же, как присланные картинки.
     *
     * def: { from: 'omnom_base', title, padX, padTop,
     *        back(c), front(c) }  — рисуют в координатах исходной картинки
     */
    derived: {},
    derive: function (name, def) { Assets.derived[name] = def; }
  };

  function buildDerived() {
    Object.keys(Assets.derived).forEach(function (name) {
      var def = Assets.derived[name];
      var src = sprites[def.from];
      var img = Assets.images[def.from];
      if (!src || !img) return;
      var padX = def.padX || 0, padTop = def.padTop || 0;
      var cv = document.createElement('canvas');
      cv.width = src.w + padX * 2;
      cv.height = src.h + padTop;
      var c = cv.getContext('2d');
      c.translate(padX, padTop);
      c.lineJoin = 'round';
      c.lineCap = 'round';
      if (def.back) { c.save(); def.back(c); c.restore(); }
      c.drawImage(img, 0, 0, src.w, src.h);
      if (def.front) { c.save(); def.front(c); c.restore(); }
      sprites[name] = {
        hero: src.hero, costume: name.slice(src.hero.length + 1), title: def.title,
        w: cv.width, h: cv.height, ax: src.ax + padX, ay: src.ay + padTop
      };
      Assets.images[name] = cv;
    });
  }

  window.Assets = Assets;
})();

